// TH15 v1.00b Stage 6 Boss2 (nonspell) — st06bs.ecl.txt:159-233
// Entry state (frame/limit/position): Boss common prologue st06bs.ecl.txt:8-34.
// Card frame 0 starts the phase; after OPENING_BUFFER the source timerReset
// (st06bs.ecl.txt:176) begins the attack window, with the source's own 120+60 f
// intro waits before the first wave (st06bs.ecl.txt:200-203).

const TIME_LIMIT: int = 2644;      // 120 buffer + 2520 source window + 4 startup margin
const OPENING_BUFFER: int = 120;
const SOURCE_WINDOW: int = 2520;   // setInterrupt timeout, st06bs.ecl.txt:195

// etSprite(0, 4, 6) st06bs.ecl.txt:239: TH15 type 4 -> TH15_BALL row, color 6.
const TH15_BALL: int = 416;
const BULLET_COLOR: int = 6;

// etAngle(0, -1.5707964f, 0.05560341f) st06bs.ecl.txt:258: mode1 fixed fan,
// alpha=-pi/2, delta=2pi/113 (0.05560341 rad ~= 65536/113 BAM).
const FAN_BASE: angle = -90deg;
const FAN_STEP: angle = 580 as angle;
const FAN_SPEED: fx = 2fx;         // etSpeed(0,2.0f,0.2f), one layer -> s0
// etDist 24.0f minus ANIM birth setback 4*velocity = 4*2.0 = 8, along each
// bullet's own angle (st06bs.ecl.txt:252-257).
const SPAWN_DIST: fx = 16fx;

// EX records st06bs.ecl.txt:252-256, all async=0:
//   OFFSCREEN a=300, WAIT a=30, ANGLE_ACCEL a=190 r=0.05 s=F0(+-0.017453292 rad).
// Birth ANIM a=1 is omitted under the approved policy; its 8px setback is kept
// in SPAWN_DIST above. The standalone WAIT 30 and the 190-frame effect remain.
xformdef CURL(omega: angle) {
    offscreen_keep(300);
    @30 add_speed(0fx);
    set_ang_vel(omega);
    set_accel(0.05fx);
    wait(190);
    stop_fx();
}

async sub boss() {
    // st06bs.ecl.txt:161-167: setInvuln(120); lifeSet(19600) is the spawn hp;
    // fresh entry has TIMEOUT==0 -> etCancel(640). No enemy bullets exist in a
    // standalone card, so the entry etCancel/etClear are omission-by-context.
    set_invuln(65535);                 // training shell: no player DPS
    set_hitbox(25fx);                  // Boss entry setHitbox(50,50) -> r=25
    set_hurtbox(28fx);                 // Boss entry setHurtbox(56,56) -> r=28
    kill_all_enemies(KILL_SILENT);     // st06bs.ecl.txt:178 enmKillAll
    // killAllAsync/spellEnd/funcSet(0)/laserCancel: no children, lasers or
    // callbacks in this card. moveVel/moveVelTime/movePosTime zeroing at
    // st06bs.ecl.txt:189-191 holds because the enemy spawns at rest.

    var rank: int = global(GVAR_RANK);
    var n: int = 112;                  // !N/!H/!LO etCount 112 (st06bs.ecl.txt:242-247)
    if rank == RANK_EASY { n = 108; }  // !E etCount 108

    sh_reset(0);
    sh_sprite(0, TH15_BALL, BULLET_COLOR);
    sh_aim(0, 0);                      // etAim(0,1): fixed fan, not aimed
    sh_ring(0, 0);                     // fan (same angle set as mode1 for even N)
    sh_count(0, n, 1);                 // etCount(N,1)
    sh_angle(0, FAN_BASE, FAN_STEP);   // etAngle(alpha,delta); earlier 0/0 is overwritten
    sh_speed(0, FAN_SPEED, 0fx);       // single speed layer
    sh_dist(0, SPAWN_DIST);

    var rot: angle = 1deg;             // diffF F0 = 0.017453292 rad (st06bs.ecl.txt:206)
    var t: int = 0;
    wait(120); t = t + 120;            // st06bs.ecl.txt:200
    wait(60);  t = t + 60;             // st06bs.ecl.txt:203

    while t < SOURCE_WINDOW {
        sh_xform(0, CURL(rot));        // Boss2_at wave, st06bs.ecl.txt:235-260
        sh_fire(0);
        if rank >= RANK_HARD {         // !HL wait(10) + second wave (st06bs.ecl.txt:210-212)
            wait(10); t = t + 10;
            sh_xform(0, CURL(rot));
            sh_fire(0);
        }
        if rank >= RANK_LUNATIC {      // !L wait(10) + third wave (st06bs.ecl.txt:213-215)
            wait(10); t = t + 10;
            sh_xform(0, CURL(rot));
            sh_fire(0);
        }
        rot = 0deg - rot;              // st06bs.ecl.txt:217 %F0 = %F0 * -1
        if rank >= RANK_LUNATIC {      // !LO 90
            wait(90); t = t + 90;
        } else {                       // !E/!N/!H 120
            wait(120); t = t + 120;
        }

        // moveRand(60,4,1.9f) + wait(60), st06bs.ecl.txt:228-229, using the
        // TH16 moveRand recipe with moveLimit(0,128,240,32) (st06bs.ecl.txt:199):
        // direction inner box x+-60 / y 120..136, position clamp x+-120 / y 112..144.
        var r: int = rand(65536) - 32768;
        var a: int = r / 3;
        if $self_x < -60fx {
            a = r / 3;
        } else if $self_x > 60fx {
            a = r / 3 + 32768;
            if a > 32768 { a = a - 65536; }
        } else {
            a = r / 4;
            var choose: int = rand(65536) % 3;
            if $player_x > $self_x {
                if choose == 0 { a = a + 32768; }
            } else {
                if choose != 0 { a = a + 32768; }
            }
        }
        if $self_y < 120fx {
            if a < 0 { a = -a; }
        } else if $self_y > 136fx {
            if a < 0 { a = -a; }
            a = -a;
        }
        // native +-pi/2 guard, epsilon 0.05 rad ~= 522 BAM
        if a > -16906 && a < -15862 {
            if a < -16384 { a = -16906; } else { a = -15862; }
        } else if a > 15862 && a < 16906 {
            if a < 16384 { a = 15862; } else { a = 16906; }
        }
        var dirx: fx = cos(a as angle);
        var diry: fx = sin(a as angle);
        var k: int = 1;                // speed(k)=1.9*(60-k)/60, first source tick is k=1
        var sp: fx = ((60 - k) as fx / 60) * 1.9fx;
        var nx: fx = $self_x + dirx * sp;
        var ny: fx = $self_y + diry * sp;
        if nx < -120fx { nx = -120fx; }
        if nx > 120fx { nx = 120fx; }
        if ny < 112fx { ny = 112fx; }
        if ny > 144fx { ny = 144fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        for i in 0..60 {
            wait(1);
            k = k + 1;
            sp = 0fx;
            if k < 60 { sp = ((60 - k) as fx / 60) * 1.9fx; }
            nx = $self_x + dirx * sp;
            ny = $self_y + diry * sp;
            if nx < -120fx { nx = -120fx; }
            if nx > 120fx { nx = 120fx; }
            if ny < 112fx { ny = 112fx; }
            if ny > 144fx { ny = 144fx; }
            move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        }
        t = t + 60;
    }
    loop { wait(60); }                 // source hands off to BossCard2; card holds here
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 19600, 0, 0, 0, boss);   // Boss entry movePos(0,128)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);   // boss entry calls enmKillAll
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
